#!/usr/bin/env python3
"""Runtime benchmark: parse time and full-stream replay time, both versions.

Protocol (ASSIGNMENT.md "Time and latency"):
  * inputs pre-generated by bench/make_data.py (outside timing);
  * each configuration runs in its own fresh Python process;
  * JSON/gzip reading+parsing is timed separately (phase "parse");
  * 1 warmup replay (repeat 0, flagged) + 5 timed replays (phase "replay"), each on a
    fresh empty book, time.perf_counter around the event loop only; results are built
    by process() and discarded (no printing, no tests, no tracing inside the loop);
  * declared limit: CONFIG_LIMIT_S wall-clock seconds per configuration. A configuration
    that exceeds it is killed; finished repeats are kept and the row is marked
    "stopped_time_limit". Once Version A is stopped for (scenario, size) at seed 42 the
    other seeds and larger sizes are recorded as "not_attempted" instead of being run.

Usage: python bench/run_timing.py            (all configurations, writes results/timing.csv)
"""
import json
import subprocess
import sys
import time

from _util import (CONFIG_LIMIT_S, MILLION, REPEATS, RESULTS, ROOT, SCENARIOS, SEEDS, SIZES,
                   VERSIONS, env_info, input_path, save_json, workload_stats, write_csv)
from lob.common import read_events


def worker(version, path):
    cls = VERSIONS[version]
    t = time.perf_counter()
    events = read_events(path)
    print(json.dumps({"phase": "parse", "repeat": 1, "elapsed_s": time.perf_counter() - t}), flush=True)
    for rep in range(REPEATS + 1):  # repeat 0 = warmup
        book = cls()
        proc = book.process
        t = time.perf_counter()
        for ev in events:
            proc(ev)
        el = time.perf_counter() - t
        print(json.dumps({"phase": "replay", "repeat": rep, "elapsed_s": el}), flush=True)


def run_config(version, path):
    cmd = [sys.executable, str(ROOT / "bench" / "run_timing.py"), "--worker", version, str(path)]
    err = ""
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=CONFIG_LIMIT_S, cwd=ROOT)
        out = proc.stdout
        status = "ok" if proc.returncode == 0 else "failed"  # a crashed worker must never count as ok
        err = (proc.stderr.strip().splitlines() or [""])[-1]
    except subprocess.TimeoutExpired as exc:
        out = exc.stdout.decode() if isinstance(exc.stdout, bytes) else (exc.stdout or "")
        status = "stopped_time_limit"
    return status, [json.loads(line) for line in out.splitlines() if line.strip()], err


def main():
    configs = [(s, n, seed) for n in SIZES for s in SCENARIOS for seed in SEEDS] + MILLION
    stats_cache = {}
    stopped_a = set()  # scenarios for which Version A hit the limit
    rows = []
    for scenario, events, seed in configs:
        path = input_path(scenario, events, seed)
        key = (scenario, events, seed)
        if key not in stats_cache:
            stats_cache[key] = workload_stats(read_events(path))
        st = stats_cache[key]
        base = {"run_kind": "timing", "scenario": scenario, "seed": seed, "events": events,
                "levels": 1000, "active_orders_peak": st["active_orders_peak"],
                "price_levels_peak": st["price_levels_peak"], "fills": st["fills"]}
        for version in VERSIONS:
            if version == "A" and scenario in stopped_a:
                rows.append({**base, "version": version, "phase": "replay", "status": "not_attempted",
                             "note": "Version A already exceeded the limit for this scenario "
                                     "at this or a smaller size"})
                print(f"{version} {scenario:12s} {events:>8d} s{seed}: not attempted", flush=True)
                continue
            t = time.perf_counter()
            status, recs, err = run_config(version, path)
            for r in recs:
                rows.append({**base, "version": version, "phase": r["phase"], "repeat": r["repeat"],
                             "elapsed_s": f"{r['elapsed_s']:.6f}",
                             "status": "warmup" if r["phase"] == "replay" and r["repeat"] == 0 else "ok"})
            done = sum(1 for r in recs if r["phase"] == "replay" and r["repeat"] > 0)
            if status != "ok":
                rows.append({**base, "version": version, "phase": "replay", "status": status,
                             "note": (f"killed after {CONFIG_LIMIT_S}s; {done} of {REPEATS} timed repeats finished"
                                      if status == "stopped_time_limit" else
                                      f"worker failed after {done} of {REPEATS} timed repeats: {err}")})
                if version == "A":
                    stopped_a.add(scenario)
            med = sorted(r["elapsed_s"] for r in recs if r["phase"] == "replay" and r["repeat"] > 0)
            med_s = f"{med[len(med) // 2]:.4f}s" if med else "-"
            print(f"{version} {scenario:12s} {events:>8d} s{seed}: {status:18s} median {med_s} "
                  f"({time.perf_counter() - t:.1f}s wall)", flush=True)
        write_csv(RESULTS / "timing.csv", rows)  # save progress after every configuration
    save_json(RESULTS / "env.json", {**env_info(), "timing_settings": {
        "repeats": REPEATS, "warmup_replays": 1, "config_limit_s": CONFIG_LIMIT_S,
        "timer": "time.perf_counter", "fresh_process_per_config": True,
        "workload_stats": {f"{s}|{n}|{seed}": v for (s, n, seed), v in stats_cache.items()}}})


if __name__ == "__main__":
    if len(sys.argv) == 4 and sys.argv[1] == "--worker":
        worker(sys.argv[2], sys.argv[3])
    else:
        main()
